brand.css:
/* מותג MSE (מטופס הדוח היומי שלהם): כחול-כהה #28333E לכותרות ולטקסט מודגש, זהב #9F7629 לכפתורים ולפסים, רקע אפור בהיר. אדום נשאר רק לשגיאות וחוסרים. */
:root{--sand:#EEEFF0;--on-accent:#FFFFFF}
.sb-today{color:#fff}
.fab{background:var(--pv);color:#fff}
.cbbar i.s{background:#B9A26F}
.top h1 .mark{width:40px;height:44px}
.top{position:relative;padding-bottom:18px}
.top::after{content:"";position:absolute;left:0;right:0;bottom:5px;height:5px;background:linear-gradient(100deg,var(--pv) 0 62%,var(--brand) 62% 100%);border-radius:3px}
.top h1,.sheet h2,.card h3,.ov-hero .big{font-family:"Heebo","Alef",Arial,sans-serif;font-weight:900}
#bqTpl,#ctTpl{display:none!important}
/* ישי 29.10: הלוגו של MSE גדול יותר בכותרת */
.top h1 .mark{width:60px;height:66px}.top h1{gap:12px}.top{padding-top:6px}.top .site{font-size:.72rem}.top .site b{font-size:.8rem}@media (max-width:380px){.top h1 .mark{width:48px;height:53px}.top h1{font-size:1.3rem;gap:8px}}
/* ישי 29.10: «למנהל יש אצבעות שמנות»: טקסט קצת גדול יותר ומטרות מגע של 52px ומעלה */
html{font-size:17px}
.tab{min-height:56px;padding:16px 6px 13px}
.ghost,.chip2,.tgl,.who-chip,.opt,.pbtn,.linkbtn,.del{min-height:52px}
.opt{padding:13px 16px;font-size:.95rem}.chip2{padding:10px 16px;font-size:.9rem}
.save,.cancel{padding:18px 16px;font-size:1.05rem;min-height:58px}
input[type=text],input[type=date],input[type=time],input[type=number],select,textarea{font-size:1.06rem;padding:15px 14px}
.fab{width:68px;height:68px}.fab-mic{font-size:1.6rem}
.slip{padding:14px;min-height:58px}.dchk input{width:26px;height:26px;flex-basis:26px}
